      const dest = matched.slice(2);
      if (inlineVal !== undefined) { values[dest] = inlineVal; i++; continue; }
      const next = argv[i + 1];
      if (next === undefined || looksLikeOption(next)) error(`argument ${matched}: expected one argument`);
      values[dest] = next; i += 2; continue;
    }
