/**
 * Python `json.loads`-compatible JSON parser.
 * Differences from JSON.parse that matter for validation semantics:
 *  - accepts NaN / Infinity / -Infinity (Python allows them by default)
 *  - distinguishes float-syntax integers ("1.0", "1e2") from int-syntax ("1"):
 *    float-syntax integral numbers are boxed in PyFloat so draft 3/4
 *    "integer" type checks can reject them, exactly like Python floats.
 *  - integers beyond Number.MAX_SAFE_INTEGER become BigInt (Python ints are
 *    arbitrary precision).
 *  - duplicate object keys keep the last value; objects are null-prototype.
 */

export class PyFloat {
  constructor(value) { this.value = value; }
  valueOf() { return this.value; }
}

const NUMBER_RE = /-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?/y;

export function pyJsonParse(text) {
  if (typeof text !== 'string') throw new TypeError('the JSON object must be str');
  let pos = 0;
  const n = text.length;

  const fail = (msg) => { throw new SyntaxError(`${msg}: line 1 column ${pos + 1} (char ${pos})`); };
