args.content:
/**
 * Python `json.loads`-compatible JSON parser.
 *
 * Differences from JSON.parse that matter for validation semantics:
 *  - accepts NaN / Infinity / -Infinity (Python's json module allows them
 *    by default),
 *  - distinguishes float-syntax integral numbers ("1.0", "1e2") from
 *    int-syntax ones ("1"): float-syntax integral numbers are boxed in a
 *    PyFloat wrapper so that draft 3/4 "integer" type checks can reject
 *    them exactly like Python floats, while arithmetic and comparisons
 *    keep working through valueOf(),
 *  - integers beyond the safe-integer range become BigInt (Python ints
 *    are arbitrary precision),
 *  - duplicate object keys keep the last value; objects are created with
 *    a null prototype so any JSON key is safe.
 */

export class PyFloat {
  constructor(value) {
    this.value = value;
  }

  valueOf() {
    return this.value;
  }
}

const NUMBER_RE = /-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?/y;

export function pyJsonParse(text) {
  if (typeof text !== 'string') {
    throw new TypeError('the JSON object must be str, not ' + typeof text);
  }
  let pos = 0;
  const n = text.length;

  function fail(msg) {
    throw new SyntaxError(`${msg}: line 1 column ${pos + 1} (char ${pos})`);
  }

  function skipWs() {
    while (pos < n) {
      const c = text[pos];
      if (c === ' ' || c === '\t' || c === '\n' || c === '\r') pos++;
      else break;
    }
  }

  function expect(word) {
    if (text.startsWith(word, pos)) pos += word.length;
    else fail('Expecting value');
  }

  function parseNumber() {
    NUMBER_RE.lastIndex = pos;
    const m = NUMBER_RE.exec(text);
    if (!m) fail('Expecting value');
    const token = m[0];
    pos += token.length;
    const isFloatSyntax = token.includes('.') || token.includes('e') || token.includes('E');
    if (isFloatSyntax) {
      const v = Number(token);
      // Box float-syntax integral values so "integer" type checks in
      // draft 3/4 can tell them apart from true ints (Python semantics).
      if (Number.isFinite(v) && Number.isInteger(v)) return new PyFloat(v);
      return v;
    }
    const v = Number(token);
    if (Number.isSafeInteger(v)) return v;
    return BigInt(token);
  }

  function parseString() {
    // text[pos] === '"'
    pos++;
    let out = '';
    while (pos < n) {
      const ch = text[pos];
      if (ch === '"') {
        pos++;
        return out;
      }
      if (ch === '\\') {
        pos++;
        if (pos >= n) break;
        const esc = text[pos++];
        switch (esc) {
          case '"': out += '"'; break;
          case '\\': out += '\\'; break;
          case '/': out += '/'; break;
          case 'b': out += '\b'; break;
          case 'f': out += '\f'; break;
          case 'n': out += '\n'; break;
          case 'r': out += '\r'; break;
          case 't': out += '\t'; break;
          case 'u': {
            const hex = text.slice(pos, pos + 4);
            if (!/^[0-9a-fA-F]{4}$/.test(hex)) fail('Invalid \\uXXXX escape');
            out += String.fromCharCode(parseInt(hex, 16));
            pos += 4;
            break;
          }
          default:
            fail('Invalid \\escape');
        }
      } else if (ch < ' ') {
        fail('Invalid control character');
      } else {
        out += ch;
        pos++;
      }
    }
    fail('Unterminated string starting');
  }

  function parseArray() {
    // text[pos] === '['
    pos++;
    const arr = [];
    skipWs();
    if (text[pos] === ']') {
      pos++;
      return arr;
    }
    for (;;) {
      arr.push(parseValue());
      skipWs();
      const c = text[pos];
      if (c === ',') {
        pos++;
        continue;
      }
      if (c === ']') {
        pos++;
        return arr;
      }
      fail("Expecting ',' delimiter");
    }
  }

  function parseObject() {
    // text[pos] === '{'
    pos++;
    const obj = Object.create(null);
    skipWs();
    if (text[pos] === '}') {
      pos++;
      return obj;
    }
    for (;;) {
      skipWs();
      if (text[pos] !== '"') fail('Expecting property name enclosed in double quotes');
      const key = parseString();
      skipWs();
      if (text[pos] !== ':') fail("Expecting ':' delimiter");
      pos++;
      obj[key] = parseValue();
      skipWs();
      const c = text[pos];
      if (c === ',') {
        pos++;
        continue;
      }
      if (c === '}') {
        pos++;
        return obj;
      }
      fail("Expecting ',' delimiter");
    }
  }

  function parseValue() {
    skipWs();
    if (pos >= n) fail('Expecting value');
    const ch = text[pos];
    if (ch === '{') return parseObject();
    if (ch === '[') return parseArray();
    if (ch === '"') return parseString();
    if (ch === 't') { expect('true'); return true; }
    if (ch === 'f') { expect('false'); return false; }
    if (ch === 'n') { expect('null'); return null; }
    if (ch === 'N') { expect('NaN'); return NaN; }
    if (ch === 'I') { expect('Infinity'); return Infinity; }
    if (ch === '-') {
      if (text.startsWith('-Infinity', pos)) {
        pos += '-Infinity'.length;
        return -Infinity;
      }
      return parseNumber();
    }
    if (ch >= '0' && ch <= '9') return parseNumber();
    fail('Expecting value');
  }

  const value = parseValue();
  skipWs();
  if (pos < n) fail('Extra data');
  return value;
}

/**
 * Python-flavoured value helpers: type predicates, equality and
 * truthiness that mirror the semantics the `jsonschema` library relies
 * on (e.g. True != 1, 1 == 1.0, NaN != NaN).
 */

import { PyFloat } from './json_parse.mjs';

export function isPyFloat(v) {
  return v instanceof PyFloat;
}

export function unbox(v) {
  return v instanceof PyFloat ? v.value : v;
}

/** A real JSON object instance (null-prototype object from the parser). */
export function isPlainObject(v) {
  return typeof v === 'object' && v !== null && !Array.isArray(v) && !(v instanceof PyFloat);
}

/** jsonschema treats boolean subschemas as "object"-typed schema values. */
export function isSchemaLike(v) {
  return isPlainObject(v) || typeof v === 'boolean';
}

export function isNumberLike(v) {
  const u = unbox(v);
  return typeof u === 'number' || typeof u === 'bigint';
}

export function toNumber(v) {
  const u = unbox(v);
  return typeof u === 'bigint' ? Number(u) : u;
}

export function pyTruthy(v) {
  const u = unbox(v);
  if (typeof u === 'bigint') return u !== 0n;
  return Boolean(u);
}

/** Python len() on a str counts Unicode code points, not UTF-16 units. */
export function codePointLength(s) {
  return Array.from(s).length;
}

export function hasOwn(obj, key) {
  return Object.prototype.hasOwnProperty.call(obj, key);
}

function bigintEqNumber(bi, num) {
  if (typeof num !== 'number') return false;
  if (Number.isNaN(num) || !Number.isFinite(num) || !Number.isInteger(num)) return false;
  return BigInt(num) === bi;
}

/** Deep equality with Python semantics: bools distinct from numbers,
 *  1 == 1.0, NaN != NaN, arrays/objects compared structurally. */
export function pyEqual(a, b) {
  const ua = unbox(a);
  const ub = unbox(b);
  const aNum = typeof ua === 'number' || typeof ua === 'bigint';
  const bNum = typeof ub === 'number' || typeof ub === 'bigint';
  if (aNum || bNum) {
    if (!(aNum && bNum)) return false;
    if (typeof ua === 'number' && Number.isNaN(ua)) return false;
    if (typeof ub === 'number' && Number.isNaN(ub)) return false;
    if (typeof ua === 'bigint' && typeof ub === 'bigint') return ua === ub;
    if (typeof ua === 'bigint') return bigintEqNumber(ua, ub);
    if (typeof ub === 'bigint') return bigintEqNumber(ub, ua);
    return ua === ub;
  }
  if (ua === null || ub === null) return ua === ub;
  if (typeof ua !== typeof ub) return false;
  if (typeof ua === 'boolean' || typeof ua === 'string') return ua === ub;
  const aArr = Array.isArray(ua);
  const bArr = Array.isArray(ub);
  if (aArr || bArr) {
    if (!aArr || !bArr || ua.length !== ub.length) return false;
    for (let i = 0; i < ua.length; i++) {
      if (!pyEqual(ua[i], ub[i])) return false;
    }
    return true;
  }
  const ka = Object.keys(ua);
  const kb = Object.keys(ub);
  if (ka.length !== kb.length) return false;
  for (const k of ka) {
    if (!hasOwn(ub, k)) return false;
    if (!pyEqual(ua[k], ub[k])) return false;
  }
  return true;
}

/** Python `jsonschema._utils.uniq`: True is distinct from 1, 1 == 1.0. */
export function isUnique(container) {
  for (let i = 0; i < container.length; i++) {
    for (let j = i + 1; j < container.length; j++) {
      if (pyEqual(container[i], container[j])) return false;
    }
  }
  return true;
}

/** Python-style modulo (%), tolerant of BigInt operands. */
export function numericMod(a, b) {
  const ua = unbox(a);
  const ub = unbox(b);
  if (typeof ua === 'bigint' && typeof ub === 'bigint') return ua % ub;
  const fa = typeof ua === 'bigint' ? Number(ua) : ua;
  const fb = typeof ub === 'bigint' ? Number(ub) : ub;
  return fa % fb;
}

/** Relational comparison on unboxed values (BigInt/Number mixes are
 *  compared exactly by JS relational operators). */
export function lt(a, b) {
  return unbox(a) < unbox(b);
}

export function lte(a, b) {
  return unbox(a) <= unbox(b);
}

export function gt(a, b) {
  return unbox(a) > unbox(b);
}

export function gte(a, b) {
  return unbox(a) >= unbox(b);
}

/**
 * $ref resolution against the root schema document: JSON Pointers
 * ("#/definitions/x"), the whole-document ref ("#") and named anchors
 * (legacy "id"/"$id" fragments, "$anchor", "$dynamicAnchor").
 * Unresolvable or remote references raise, mirroring the Python
 * `jsonschema`/`referencing` behaviour of failing hard.
 */

import { isPlainObject } from './pytypes.mjs';

function resolvePointer(doc, pointer) {
  const decoded = decodeURIComponent(pointer);
  const parts = decoded
    .split('/')
    .slice(1)
    .map((p) => p.replace(/~1/g, '/').replace(/~0/g, '~'));
  let current = doc;
  for (const part of parts) {
    if (Array.isArray(current)) {
      if (!/^(0|[1-9][0-9]*)$/.test(part)) {
        throw new Error(`Unresolvable JSON pointer: ${pointer}`);
      }
      const idx = Number(part);
      if (idx >= current.length) {
        throw new Error(`Unresolvable JSON pointer: ${pointer}`);
      }
      current = current[idx];
    } else if (isPlainObject(current)) {
      if (!Object.prototype.hasOwnProperty.call(current, part)) {
        throw new Error(`Unresolvable JSON pointer: ${pointer}`);
      }
      current = current[part];
    } else {
      throw new Error(`Unresolvable JSON pointer: ${pointer}`);
    }
  }
  return current;
}

export function createResolver(root) {
  let anchors = null;

  function collectAnchors() {
    anchors = new Map();
    const seen = new Set();
    const walk = (node) => {
      if (Array.isArray(node)) {
        for (const item of node) walk(item);
        return;
      }
      if (!isPlainObject(node) || seen.has(node)) return;
      seen.add(node);
      for (const key of ['$anchor', '$dynamicAnchor']) {
        if (typeof node[key] === 'string' && !anchors.has(node[key])) {
          anchors.set(node[key], node);
        }
      }
      for (const key of ['$id', 'id']) {
        const v = node[key];
        if (typeof v === 'string' && v.startsWith('#') && v.length > 1 && !v.startsWith('#/')) {
          const name = decodeURIComponent(v.slice(1));
          if (!anchors.has(name)) anchors.set(name, node);
        }
      }
      for (const v of Object.values(node)) walk(v);
    };
    walk(root);
  }

  function resolve(ref) {
    if (typeof ref !== 'string') {
      throw new TypeError(`Unresolvable reference: ${String(ref)}`);
    }
    if (ref === '#') return root;
    if (ref.startsWith('#/')) return resolvePointer(root, ref.slice(1));
    if (ref.startsWith('#')) {
      if (anchors === null) collectAnchors();
      const name = decodeURIComponent(ref.slice(1));
      if (anchors.has(name)) return anchors.get(name);
      throw new Error(`Unresolvable reference: ${ref}`);
    }
    throw new Error(`Unresolvable reference: ${ref}`);
  }

  return { resolve };
}

/**
 * Keyword validators, mirroring the error-yielding granularity of the
 * Python `jsonschema` package: each generator yields one marker per
 * individual ValidationError that `iter_errors` would produce, so that
 * counting them reproduces `len(list(validator.iter_errors(instance)))`.
 */

import {
  codePointLength,
  gt,
  gte,
  hasOwn,
  isPlainObject,
  isPyFloat,
  isSchemaLike,
  isUnique,
  lt,
  lte,
  numericMod,
  pyEqual,
  pyTruthy,
  toNumber,
  unbox,
} from './pytypes.mjs';

/** Shared marker object for a single validation error (only the count
 *  of yielded errors is observed, so one frozen marker is enough). */
export const ERR = Object.freeze({ validationError: true });

function typeError(msg) {
  return new TypeError(msg);
}

/* ------------------------------------------------------------------ */
/* numeric keywords                                                    */
/* ------------------------------------------------------------------ */

export function* multipleOf(validator, dB, instance) {
  if (!validator.isType(instance, 'number')) return;
  const dbu = unbox(dB);
  const dbIsFloat = isPyFloat(dB) || (typeof dbu === 'number' && !Number.isInteger(dbu));
  let failed;
  if (dbIsFloat) {
    const quotient = toNumber(instance) / toNumber(dB);
    if (Number.isNaN(quotient)) {
      // Python: int(float('nan')) raises ValueError.
      throw typeError('cannot convert float NaN to integer');
    }
    failed = !Number.isFinite(quotient) ? true : Math.trunc(quotient) !== quotient;
  } else {
    failed = pyTruthy(numericMod(instance, dB));
  }
  if (failed) yield ERR;
}

export function* minimum(validator, minimum, instance) {
  if (!validator.isType(instance, 'number')) return;
  if (lt(instance, minimum)) yield ERR;
}

export function* maximum(validator, maximum, instance) {
  if (!validator.isType(instance, 'number')) return;
  if (gt(instance, maximum)) yield ERR;
}

export function* exclusiveMinimum(validator, exclusiveMinimum, instance) {
  if (!validator.isType(instance, 'number')) return;
  if (lte(instance, exclusiveMinimum)) yield ERR;
}

export function* exclusiveMaximum(validator, exclusiveMaximum, instance) {
  if (!validator.isType(instance, 'number')) return;
  if (gte(instance, exclusiveMaximum)) yield ERR;
}

/** Draft 3/4: exclusiveMinimum/exclusiveMaximum are boolean modifiers. */
export function* minimumLegacy(validator, minimum, instance, schema) {
  if (!validator.isType(instance, 'number')) return;
  const exclusive = hasOwn(schema, 'exclusiveMinimum') && pyTruthy(schema.exclusiveMinimum);
  const failed = exclusive ? lte(instance, minimum) : lt(instance, minimum);
  if (failed) yield ERR;
}

export function* maximumLegacy(validator, maximum, instance, schema) {
  if (!validator.isType(instance, 'number')) return;
  const exclusive = hasOwn(schema, 'exclusiveMaximum') && pyTruthy(schema.exclusiveMaximum);
  const failed = exclusive ? gte(instance, maximum) : gt(instance, maximum);
  if (failed) yield ERR;
}

/* ------------------------------------------------------------------ */
/* string keywords                                                     */
/* ------------------------------------------------------------------ */

export function* minLength(validator, minLength, instance) {
  if (!validator.isType(instance, 'string')) return;
  if (codePointLength(instance) < unbox(minLength)) yield ERR;
}

export function* maxLength(validator, maxLength, instance) {
  if (!validator.isType(instance, 'string')) return;
  if (codePointLength(instance) > unbox(maxLength)) yield ERR;
}

function compilePattern(pattern) {
  if (typeof pattern !== 'string') throw typeError('pattern must be a string');
  return new RegExp(pattern, 'u');
}

export function* pattern(validator, patternValue, instance) {
  if (!validator.isType(instance, 'string')) return;
  if (!compilePattern(patternValue).test(instance)) yield ERR;
}

/* ------------------------------------------------------------------ */
/* array keywords                                                      */
/* ------------------------------------------------------------------ */

export function* minItems(validator, minItems, instance) {
  if (!validator.isType(instance, 'array')) return;
  if (instance.length < unbox(minItems)) yield ERR;
}

export function* maxItems(validator, maxItems, instance) {
  if (!validator.isType(instance, 'array')) return;
  if (instance.length > unbox(maxItems)) yield ERR;
}

export function* uniqueItems(validator, uniqueItems, instance) {
  if (!validator.isType(instance, 'array')) return;
  if (pyTruthy(uniqueItems) && !isUnique(instance)) yield ERR;
}

/** Draft 3-2019/09: "items" is a schema or an array of schemas. */
export function* itemsLegacy(validator, items, instance, schema) {
  if (!validator.isType(instance, 'array')) return;
  if (isSchemaLike(items)) {
    for (let i = 0; i < instance.length; i++) {
      yield* validator.descend(instance[i], items);
    }
  } else if (Array.isArray(items)) {
    const n = Math.min(instance.length, items.length);
    for (let i = 0; i < n; i++) {
      yield* validator.descend(instance[i], items[i]);
    }
  } else {
    throw typeError('items must be a schema or an array of schemas');
  }
}

/** Draft 3-2019/09: applies to indexes past an array-form "items". */
export function* additionalItemsLegacy(validator, aI, instance, schema) {
  if (!validator.isType(instance, 'array')) return;
  const items = hasOwn(schema, 'items') ? schema.items : undefined;
  if (isSchemaLike(items)) return;
  if (!Array.isArray(items)) return;
  const lenItems = items.length;
  if (isSchemaLike(aI)) {
    for (let i = lenItems; i < instance.length; i++) {
      yield* validator.descend(instance[i], aI);
    }
  } else if (!pyTruthy(aI) && instance.length > lenItems) {
    yield ERR;
  }
}

/** Draft 2020-12. */
export function* prefixItems(validator, prefixItems, instance) {
  if (!validator.isType(instance, 'array')) return;
  if (!Array.isArray(prefixItems)) throw typeError('prefixItems must be an array');
  const n = Math.min(instance.length, prefixItems.length);
  for (let i = 0; i < n; i++) {
    yield* validator.descend(instance[i], prefixItems[i]);
  }
}

/** Draft 2020-12: "items" is a single schema applying past prefixItems. */
export function* items2020(validator, items, instance, schema) {
  if (!validator.isType(instance, 'array')) return;
  const prefix = Array.isArray(schema.prefixItems) ? schema.prefixItems.length : 0;
  for (let i = prefix; i < instance.length; i++) {
    yield* validator.descend(instance[i], items);
  }
}

/** Draft 6/7: plain contains, no min/maxContains. */
export function* containsSimple(validator, contains, instance) {
  if (!validator.isType(instance, 'array')) return;
  for (const item of instance) {
    if (validator.isValidUnder(contains, item)) return;
  }
  yield ERR;
}

/** Draft 2019-09 / 2020-12: contains with minContains / maxContains. */
export function* containsBounded(validator, contains, instance, schema) {
  if (!validator.isType(instance, 'array')) return;
  const minContains = hasOwn(schema, 'minContains') ? schema.minContains : 1;
  const maxContains = hasOwn(schema, 'maxContains') ? schema.maxContains : instance.length;
  let matches = 0;
  for (const item of instance) {
    if (validator.isValidUnder(contains, item)) {
      matches++;
      if (gt(matches, maxContains)) {
        yield ERR;
        return;
      }
    }
  }
  if (lt(matches, minContains)) yield ERR;
}

/* ------------------------------------------------------------------ */
/* object keywords                                                     */
/* ------------------------------------------------------------------ */

export function* minProperties(validator, minProperties, instance) {
  if (!validator.isType(instance, 'object')) return;
  if (Object.keys(instance).length < unbox(minProperties)) yield ERR;
}

export function* maxProperties(validator, maxProperties, instance) {
  if (!validator.isType(instance, 'object')) return;
  if (Object.keys(instance).length > unbox(maxProperties)) yield ERR;
}

export function* required(validator, required, instance) {
  if (!validator.isType(instance, 'object')) return;
  if (!Array.isArray(required)) throw typeError('required must be an array');
  for (const property of required) {
    if (!hasOwn(instance, property)) yield ERR;
  }
}

export function* properties(validator, properties, instance) {
  if (!validator.isType(instance, 'object')) return;
  if (!isPlainObject(properties)) throw typeError('properties must be an object');
  for (const [property, subschema] of Object.entries(properties)) {
    if (hasOwn(instance, property)) {
      yield* validator.descend(instance[property], subschema);
    }
  }
}

export function* patternProperties(validator, patternProperties, instance) {
  if (!validator.isType(instance, 'object')) return;
  if (!isPlainObject(patternProperties)) throw typeError('patternProperties must be an object');
  for (const [pattern, subschema] of Object.entries(patternProperties)) {
    let re = null;
    for (const key of Object.keys(instance)) {
      if (re === null) re = compilePattern(pattern);
      if (re.test(key)) yield* validator.descend(instance[key], subschema);
    }
  }
}

function propertyExtras(instance, schema) {
  const props = hasOwn(schema, 'properties') ? schema.properties : undefined;
  const pats = hasOwn(schema, 'patternProperties') ? schema.patternProperties : undefined;
  const patKeys = isPlainObject(pats) ? Object.keys(pats) : [];
  const extras = [];
  for (const key of Object.keys(instance)) {
    if (isPlainObject(props) && hasOwn(props, key)) continue;
    if (Array.isArray(props) && props.includes(key)) continue;
    let matched = false;
    for (const p of patKeys) {
      if (compilePattern(p).test(key)) {
        matched = true;
        break;
      }
    }
    if (!matched) extras.push(key);
  }
  return extras;
}

export function* additionalProperties(validator, aP, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  const extras = propertyExtras(instance, schema);
  if (isSchemaLike(aP)) {
    for (const key of extras) {
      yield* validator.descend(instance[key], aP);
    }
  } else if (!pyTruthy(aP)) {
    for (let i = 0; i < extras.length; i++) yield ERR;
  }
}

/** Draft 3-7 "dependencies": array form yields one error per missing
 *  dependency; schema form descends into the subschema. */
export function* dependencies(validator, dependencies, instance) {
  if (!validator.isType(instance, 'object')) return;
  if (!isPlainObject(dependencies)) throw typeError('dependencies must be an object');
  for (const [property, dependency] of Object.entries(dependencies)) {
    if (!hasOwn(instance, property)) continue;
    if (isSchemaLike(dependency)) {
      yield* validator.descend(instance, dependency);
    } else if (Array.isArray(dependency)) {
      for (const dep of dependency) {
        if (!hasOwn(instance, dep)) yield ERR;
      }
    } else {
      throw typeError('dependency must be an array or a schema');
    }
  }
}

/** Draft 2019-09+. */
export function* dependentRequired(validator, dependentRequired, instance) {
  if (!validator.isType(instance, 'object')) return;
  if (!isPlainObject(dependentRequired)) throw typeError('dependentRequired must be an object');
  for (const [property, dependency] of Object.entries(dependentRequired)) {
    if (!hasOwn(instance, property)) continue;
    if (!Array.isArray(dependency)) throw typeError('dependency must be an array');
    for (const dep of dependency) {
      if (!hasOwn(instance, dep)) yield ERR;
    }
  }
}

/** Draft 2019-09+. */
export function* dependentSchemas(validator, dependentSchemas, instance) {
  if (!validator.isType(instance, 'object')) return;
  if (!isPlainObject(dependentSchemas)) throw typeError('dependentSchemas must be an object');
  for (const [property, subschema] of Object.entries(dependentSchemas)) {
    if (!hasOwn(instance, property)) continue;
    yield* validator.descend(instance, subschema);
  }
}

export function* propertyNames(validator, propertyNames, instance) {
  if (!validator.isType(instance, 'object')) return;
  for (const key of Object.keys(instance)) {
    yield* validator.descend(key, propertyNames);
  }
}

/* ------------------------------------------------------------------ */
/* applicators                                                         */
/* ------------------------------------------------------------------ */

export function* allOf(validator, allOf, instance) {
  if (!Array.isArray(allOf)) throw typeError('allOf must be an array');
  for (const subschema of allOf) {
    yield* validator.descend(instance, subschema);
  }
}

export function* anyOf(validator, anyOf, instance) {
  if (!Array.isArray(anyOf)) throw typeError('anyOf must be an array');
  for (const subschema of anyOf) {
    if (validator.isValidUnder(subschema, instance)) return;
  }
  yield ERR;
}

export function* oneOf(validator, oneOf, instance) {
  if (!Array.isArray(oneOf)) throw typeError('oneOf must be an array');
  let valids = 0;
  for (const subschema of oneOf) {
    if (validator.isValidUnder(subschema, instance)) valids++;
  }
  if (valids !== 1) yield ERR;
}

export function* not_(validator, not, instance) {
  if (validator.isValidUnder(not, instance)) yield ERR;
}

export function* if_(validator, ifSchema, instance, schema) {
  if (validator.isValidUnder(ifSchema, instance)) {
    if (hasOwn(schema, 'then')) yield* validator.descend(instance, schema.then);
  } else if (hasOwn(schema, 'else')) {
    yield* validator.descend(instance, schema.else);
  }
}

export function* ref(validator, refValue, instance) {
  const resolved = validator.resolveRef(refValue);
  yield* validator.descend(instance, resolved);
}

/* ------------------------------------------------------------------ */
/* equality keywords                                                   */
/* ------------------------------------------------------------------ */

export function* enum_(validator, enums, instance) {
  if (!Array.isArray(enums)) throw typeError('enum must be an array');
  for (const e of enums) {
    if (pyEqual(e, instance)) return;
  }
  yield ERR;
}

export function* const_(validator, constValue, instance) {
  if (!pyEqual(constValue, instance)) yield ERR;
}

/* ------------------------------------------------------------------ */
/* type                                                                */
/* ------------------------------------------------------------------ */

export function* type_(validator, types, instance) {
  if (typeof types === 'string') types = [types];
  if (!Array.isArray(types)) throw typeError('type must be a string or an array');
  for (const t of types) {
    if (typeof t !== 'string') throw typeError('type entries must be strings');
    if (validator.isType(instance, t)) return;
  }
  yield ERR;
}

/** Draft 3: "type" entries may also be subschemas; "any" matches all. */
export function* typeDraft3(validator, types, instance) {
  if (!Array.isArray(types)) types = [types];
  for (const t of types) {
    if (isSchemaLike(t)) {
      if (validator.isValidUnder(t, instance)) return;
    } else if (typeof t === 'string') {
      if (validator.isType(instance, t)) return;
    } else {
      throw typeError('type entries must be strings or schemas');
    }
  }
  yield ERR;
}

/** Draft 3: "disallow" is the negated "type". */
export function* disallowDraft3(validator, disallow, instance) {
  const list = Array.isArray(disallow) ? disallow : [disallow];
  for (const d of list) {
    if (typeof d !== 'string') throw typeError('disallow entries must be strings');
    if (validator.isType(instance, d)) yield ERR;
  }
}

/** Draft 3: "extends" takes a schema or an array of schemas. */
export function* extendsDraft3(validator, extends_, instance) {
  if (isSchemaLike(extends_)) {
    yield* validator.descend(instance, extends_);
  } else if (Array.isArray(extends_)) {
    for (const subschema of extends_) {
      yield* validator.descend(instance, subschema);
    }
  } else {
    throw typeError('extends must be a schema or an array of schemas');
  }
}

/** Draft 3: "required" is a boolean inside property subschemas. */
export function* propertiesDraft3(validator, properties, instance) {
  if (!validator.isType(instance, 'object')) return;
  if (!isPlainObject(properties)) throw typeError('properties must be an object');
  for (const [property, subschema] of Object.entries(properties)) {
    if (hasOwn(instance, property)) {
      yield* validator.descend(instance[property], subschema);
    } else if (
      isPlainObject(subschema) &&
      hasOwn(subschema, 'required') &&
      pyTruthy(subschema.required)
    ) {
      yield ERR;
    }
  }
}

/* ------------------------------------------------------------------ */
/* unevaluatedProperties / unevaluatedItems (draft 2019-09+)           */
/* ------------------------------------------------------------------ */

function mergeInto(target, source) {
  for (const v of source) target.add(v);
}

function findEvaluatedProps(validator, instance, schema, seen) {
  const evaluated = new Set();
  if (!isPlainObject(schema) || seen.has(schema)) return evaluated;
  seen.add(schema);

  const props = schema.properties;
  if (isPlainObject(props)) {
    for (const k of Object.keys(props)) {
      if (hasOwn(instance, k)) evaluated.add(k);
    }
  }
  const pats = schema.patternProperties;
  if (isPlainObject(pats)) {
    for (const p of Object.keys(pats)) {
      const re = compilePattern(p);
      for (const k of Object.keys(instance)) {
        if (re.test(k)) evaluated.add(k);
      }
    }
  }
  if (hasOwn(schema, 'additionalProperties') && isSchemaLike(schema.additionalProperties)) {
    for (const k of propertyExtras(instance, schema)) evaluated.add(k);
  }
  if (Array.isArray(schema.allOf)) {
    for (const sub of schema.allOf) {
      mergeInto(evaluated, findEvaluatedProps(validator, instance, sub, seen));
    }
  }
  for (const key of ['anyOf', 'oneOf']) {
    if (Array.isArray(schema[key])) {
      for (const sub of schema[key]) {
        if (validator.isValidUnder(sub, instance)) {
          mergeInto(evaluated, findEvaluatedProps(validator, instance, sub, seen));
        }
      }
    }
  }
  if (hasOwn(schema, 'if')) {
    mergeInto(evaluated, findEvaluatedProps(validator, instance, schema.if, seen));
    if (validator.isValidUnder(schema.if, instance)) {
      if (hasOwn(schema, 'then')) {
        mergeInto(evaluated, findEvaluatedProps(validator, instance, schema.then, seen));
      }
    } else if (hasOwn(schema, 'else')) {
      mergeInto(evaluated, findEvaluatedProps(validator, instance, schema.else, seen));
    }
  }
  for (const rk of ['$ref', '$dynamicRef', '$recursiveRef']) {
    if (hasOwn(schema, rk)) {
      mergeInto(
        evaluated,
        findEvaluatedProps(validator, instance, validator.resolveRef(schema[rk]), seen),
      );
    }
  }
  if (isPlainObject(schema.dependentSchemas)) {
    for (const [k, sub] of Object.entries(schema.dependentSchemas)) {
      if (hasOwn(instance, k)) {
        mergeInto(evaluated, findEvaluatedProps(validator, instance, sub, seen));
      }
    }
  }
  return evaluated;
}

export function* unevaluatedProperties(validator, uP, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  const evaluated = findEvaluatedProps(validator, instance, schema, new Set());
  const unevaluated = [];
  for (const k of Object.keys(instance)) {
    if (!evaluated.has(k)) unevaluated.push(k);
  }
  if (isSchemaLike(uP)) {
    for (const k of unevaluated) {
      yield* validator.descend(instance[k], uP);
    }
  } else if (!pyTruthy(uP) && unevaluated.length > 0) {
    yield ERR;
  }
}

function findEvaluatedItems(validator, instance, schema, seen) {
  const evaluated = new Set();
  if (!isPlainObject(schema) || seen.has(schema)) return evaluated;
  seen.add(schema);

  if (Array.isArray(schema.prefixItems)) {
    const n = Math.min(schema.prefixItems.length, instance.length);
    for (let i = 0; i < n; i++) evaluated.add(i);
  }
  if (hasOwn(schema, 'items')) {
    const items = schema.items;
    if (Array.isArray(items)) {
      // legacy (draft 2019-09) array form
      const n = Math.min(items.length, instance.length);
      for (let i = 0; i < n; i++) evaluated.add(i);
      if (hasOwn(schema, 'additionalItems') && isSchemaLike(schema.additionalItems)) {
        for (let i = items.length; i < instance.length; i++) evaluated.add(i);
      }
    } else if (isSchemaLike(items)) {
      const start = Array.isArray(schema.prefixItems) ? schema.prefixItems.length : 0;
      for (let i = start; i < instance.length; i++) evaluated.add(i);
    }
  }
  if (hasOwn(schema, 'contains') && isSchemaLike(schema.contains)) {
    for (let i = 0; i < instance.length; i++) {
      if (validator.isValidUnder(schema.contains, instance[i])) evaluated.add(i);
    }
  }
  if (Array.isArray(schema.allOf)) {
    for (const sub of schema.allOf) {
      mergeInto(evaluated, findEvaluatedItems(validator, instance, sub, seen));
    }
  }
  for (const key of ['anyOf', 'oneOf']) {
    if (Array.isArray(schema[key])) {
      for (const sub of schema[key]) {
        if (validator.isValidUnder(sub, instance)) {
          mergeInto(evaluated, findEvaluatedItems(validator, instance, sub, seen));
        }
      }
    }
  }
  if (hasOwn(schema, 'if')) {
    mergeInto(evaluated, findEvaluatedItems(validator, instance, schema.if, seen));
    if (validator.isValidUnder(schema.if, instance)) {
      if (hasOwn(schema, 'then')) {
        mergeInto(evaluated, findEvaluatedItems(validator, instance, schema.then, seen));
      }
    } else if (hasOwn(schema, 'else')) {
      mergeInto(evaluated, findEvaluatedItems(validator, instance, schema.else, seen));
    }
  }
  for (const rk of ['$ref', '$dynamicRef', '$recursiveRef']) {
    if (hasOwn(schema, rk)) {
      mergeInto(
        evaluated,
        findEvaluatedItems(validator, instance, validator.resolveRef(schema[rk]), seen),
      );
    }
  }
  return evaluated;
}

export function* unevaluatedItems(validator, uI, instance, schema) {
  if (!validator.isType(instance, 'array')) return;
  const evaluated = findEvaluatedItems(validator, instance, schema, new Set());
  const unevaluated = [];
  for (let i = 0; i < instance.length; i++) {
    if (!evaluated.has(i)) unevaluated.push(i);
  }
  if (isSchemaLike(uI)) {
    for (const i of unevaluated) {
      yield* validator.descend(instance[i], uI);
    }
  } else if (!pyTruthy(uI) && unevaluated.length > 0) {
    yield ERR;
  }
}

/**
 * Per-draft validator definitions: which keywords each draft validates,
 * whether "$ref" overrides its sibling keywords, and whether the
 * "integer" type rejects float-syntax values (draft 3/4 semantics).
 * Meta-schema IDs are stored fragment-less (URIDict normalization).
 */

import * as K from './keywords.mjs';

const draft3Keywords = {
  $ref: K.ref,
  additionalItems: K.additionalItemsLegacy,
  additionalProperties: K.additionalProperties,
  dependencies: K.dependencies,
  disallow: K.disallowDraft3,
  divisibleBy: K.multipleOf,
  enum: K.enum_,
  extends: K.extendsDraft3,
  items: K.itemsLegacy,
  maximum: K.maximumLegacy,
  minimum: K.minimumLegacy,
  maxItems: K.maxItems,
  maxLength: K.maxLength,
  minItems: K.minItems,
  minLength: K.minLength,
  pattern: K.pattern,
  patternProperties: K.patternProperties,
  properties: K.propertiesDraft3,
  type: K.typeDraft3,
  uniqueItems: K.uniqueItems,
};

const draft4Keywords = {
  $ref: K.ref,
  additionalItems: K.additionalItemsLegacy,
  additionalProperties: K.additionalProperties,
  allOf: K.allOf,
  anyOf: K.anyOf,
  dependencies: K.dependencies,
  enum: K.enum_,
  items: K.itemsLegacy,
  maximum: K.maximumLegacy,
  minimum: K.minimumLegacy,
  maxItems: K.maxItems,
  maxLength: K.maxLength,
  maxProperties: K.maxProperties,
  minItems: K.minItems,
  minLength: K.minLength,
  minProperties: K.minProperties,
  multipleOf: K.multipleOf,
  not: K.not_,
  oneOf: K.oneOf,
  pattern: K.pattern,
  patternProperties: K.patternProperties,
  properties: K.properties,
  required: K.required,
  type: K.type_,
  uniqueItems: K.uniqueItems,
};

const draft6Keywords = {
  ...draft4Keywords,
  // draft 6 made exclusiveMinimum/exclusiveMaximum standalone numbers
  minimum: K.minimum,
  maximum: K.maximum,
  exclusiveMinimum: K.exclusiveMinimum,
  exclusiveMaximum: K.exclusiveMaximum,
  const: K.const_,
  contains: K.containsSimple,
  propertyNames: K.propertyNames,
};

const draft7Keywords = {
  ...draft6Keywords,
  if: K.if_,
};

const draft201909Keywords = {
  ...draft7Keywords,
  contains: K.containsBounded,
  dependentRequired: K.dependentRequired,
  dependentSchemas: K.dependentSchemas,
  unevaluatedItems: K.unevaluatedItems,
  unevaluatedProperties: K.unevaluatedProperties,
  $recursiveRef: K.ref,
};

const draft202012Keywords = {
  ...draft201909Keywords,
  items: K.items2020,
  prefixItems: K.prefixItems,
  $dynamicRef: K.ref,
};
delete draft202012Keywords.additionalItems;

export const Draft3Validator = {
  __name__: 'Draft3Validator',
