export function createResolver(root, klass) {
  let anchors = null;
  const idKey = klass.idKey; // 'id' for draft 3/4, '$id' for later drafts
  const anchorKeys = [];
  if (klass.supportsAnchor) anchorKeys.push('$anchor');
  if (klass.supportsDynamicAnchor) anchorKeys.push('$dynamicAnchor');

  function collectAnchors() {
    anchors = new Map();
    const seen = new Set();
    const walk = (node) => {
      if (Array.isArray(node)) {
        for (const item of node) walk(item);
        return;
      }
      if (!isPlainObject(node) || seen.has(node)) return;
      seen.add(node);
      for (const key of anchorKeys) {
        if (typeof node[key] === 'string' && !anchors.has(node[key])) {
          anchors.set(node[key], node);
        }
      }
      const v = node[idKey];
      if (typeof v === 'string' && v.startsWith('#') && v.length > 1 && !v.startsWith('#/')) {
        const name = decodeURIComponent(v.slice(1));
        if (!anchors.has(name)) anchors.set(name, node);
      }
      for (const val of Object.values(node)) walk(val);
    };
    walk(root);
  }

