export function* required(validator, required, instance) {
  if (!validator.isType(instance, 'object')) return;
  // Python iterates the keyword value directly: arrays element-wise,
  // (invalid) strings character by character.
  if (!Array.isArray(required) && typeof required !== 'string') {
    throw new TypeError('required must be an array');
  }
  for (const property of required) {
    if (!hasOwn(instance, property)) yield ERR;
  }
}

